# hypothesis: a subclass that leaves an abstract property unimplemented is rejected both statically and at runtime, while a subclass that overrides it with a property is accepted.
from abc import ABC, abstractmethod
from typing import assert_type, reveal_type


class Shape(ABC):
    @property
    @abstractmethod
    def sides(self) -> int:
        raise NotImplementedError

    @abstractmethod
    def area(self) -> float:
        raise NotImplementedError


class Square(Shape):
    def __init__(self, size: float) -> None:
        self.size = size

    @property
    def sides(self) -> int:
        return 4

    def area(self) -> float:
        return self.size * self.size


class Blob(Shape):
    def area(self) -> float:
        return 0.0


def describe(s: Shape) -> str:
    return f'{s.sides} sides, area {s.area()}'


sq = Square(2.0)
reveal_type(sq.sides)
assert_type(sq.sides, int)
print(describe(sq))


def make_blob() -> Shape:
    return Blob()  # expect-error: Blob does not implement abstract property sides


try:
    make_blob()
except TypeError as exc:
    print('runtime:', type(exc).__name__)

try:
    Shape()  # expect-error: Shape is abstract
except TypeError as exc:
    print('runtime:', type(exc).__name__)
